'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (v,d=0) => Number(v||0).toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d});
const state = {tab:'overview', runId:null, data:null, view:'drawing', selected:'count', page:1, pages:1, selectedItem:0, scene:null};
const icons = {overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',drawings:'<path d="M5 3h10l4 4v14H5zM15 3v5h4M8 12h8M8 16h5"/>',review:'<path d="M8 4h12v16H4V8M8 3v5H3M8 14l3 3 6-7"/>',results:'<path d="M4 4h16v16H4zM4 9h16M10 4v16M4 15h16"/>',evidence:'<path d="M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 11l3 3 5-6"/>',capabilities:'<path d="M12 2l2 7 7 3-7 2-2 8-2-8-8-2 8-3z"/>'};
const navs = [['overview','Overview'],['drawings','Drawing intelligence'],['review','Review & approve'],['results','Bar schedule'],['evidence','Evidence & workflow'],['capabilities','AI capabilities']];
/* Inline icon set. One visual language — no emoji, which render differently on
   every machine a demo might run on. */
const ui = {
  arrowRight:'<path d="M5 12h14M13 6l6 6-6 6"/>',
  arrowUpRight:'<path d="M7 17L17 7M9 7h8v8"/>',
  download:'<path d="M12 3v12M7 11l5 5 5-5M4 20h16"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  wand:'<path d="M4 20l10-10M14 4l1.6 3.4L19 9l-3.4 1.6L14 14l-1.6-3.4L9 9l3.4-1.6z"/>',
  check:'<path d="M4 12.5l5 5L20 6"/>',
  stop:'<rect x="6" y="6" width="12" height="12" rx="1.5"/>',
  play:'<path d="M6 4l14 8-14 8z"/>',
  close:'<path d="M6 6l12 12M18 6L6 18"/>',
  chevL:'<path d="M15 6l-6 6 6 6"/>',
  chevR:'<path d="M9 6l6 6-6 6"/>',
  shield:'<path d="M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 11l3 3 5-6"/>',
};
const ic = (name, size = 14) => `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ui[name]}</svg>`;
async function api(path,options){const r=await fetch(path,options);if(!r.ok){let m;try{m=(await r.json()).detail;}catch{m=r.statusText;}throw Error(typeof m==='string'?m:JSON.stringify(m));}return r.json();}
const post = (path,body)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function tag(text,color=''){return `<span class="tag ${color}">${esc(text)}</span>`;}
function button(text,action,style=''){return `<button class="button ${style}" onclick="${action}">${text}</button>`;}
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${state.data?.seeded?'Atlantic Cages / Pile reinforcement':'Engineering workspace'}</div><h1>${title}</h1><p>${sub}</p></div><div class="toolbar">${actions}</div></div>`;}
function metric(label,value,note,color=''){return `<div class="metric${color?' metric-'+color:''}"><div class="metric-top"><span>${label}</span>${color?tag(color==='green'?'Verified':'Action needed',color):''}</div><div class="value">${value}</div><small>${note}</small></div>`;}
function updateNav(){ $('#nav').innerHTML=navs.map(([id,label])=>`<button title="${label}" onclick="go('${id}')" class="${id===state.tab?'active':''}"><svg viewBox="0 0 24 24">${icons[id]}</svg><span class="nav-text">${label}</span>${id==='review'&&state.data?.questions.length?`<span class="count">${state.data.questions.length}</span>`:id==='review'&&state.data?.run.state==='suspended'&&state.data?.run.pending_step===19?'<span class="count">!</span>':''}</button>`).join('');$('#breadcrumb').textContent=navs.find(n=>n[0]===state.tab)[1];$('#data-basis').textContent=state.data?.seeded?'SAMPLE PROJECT':'PDF PROJECT';}
async function refresh(){state.data=await api(`/runs/${state.runId}/workspace`);updateNav();}
function go(tab){state.tab=tab;updateNav();render();window.scrollTo({top:0,behavior:'instant'});const m=$('#main');m.classList.remove('fade-in');void m.offsetWidth;m.classList.add('fade-in');}
function render(){if(!state.data)return;({overview,drawings,review,results,evidence,capabilities}[state.tab])();}
async function start(scenario='clarification',project_id='atlantic-demo'){ $('#modal').close();$('#main').innerHTML='<div class="loading"><span class="spinner"></span>Reading inputs and checking the evidence…</div>';try{let r=await post('/runs',{project_id,scenario});state.runId=r.run_id;localStorage.setItem('trustsight-run',r.run_id);state.scene=null;state.page=1;state.selectedItem=0;await refresh();state.pages=(await api(`/runs/${state.runId}/document`)).pages;go('overview');toast(scenario==='conflict'?'Conflict scenario ready. No bars can be released.':scenario==='structured'?'Structured run ready. Every fact was known; nothing needs clarification.':scenario==='approval'?'Calculation complete. Awaiting an engineer’s rulebook sign-off before release.':'Run ready. Review the drawing and resolve the missing details.');}catch(e){$('#main').innerHTML=`<div class="empty"><strong>Could not start the run</strong>${esc(e.message)}<p>${button('Try again',"start()")}</p></div>`;}}
function newRun(){ $('#modal-body').innerHTML=`<div class="modal-head"><h2>Choose your demonstration</h2><button class="quiet" onclick="$('#modal').close()" aria-label="Close">${ic('close',16)}</button></div><div class="modal-content"><p>Each scenario runs the calculation and governance engine end to end.</p><button class="scenario-option" onclick="start('clarification')"><strong>01 / From missing detail to released schedule →</strong><span>Inspect a pile, approve two sample clarifications, then trace the calculated result.</span></button><button class="scenario-option" onclick="start('conflict')"><strong>02 / Catch a conflicting pile count →</strong><span>The plan says 8. The schedule says 6. Watch the engine block release.</span></button><button class="scenario-option" onclick="start('structured')"><strong>03 / Everything known: instant release →</strong><span>A complete native-text drawing needs no clarification. Watch the schedule release immediately.</span></button><button class="scenario-option" onclick="start('approval')"><strong>04 / Block release until an engineer signs off →</strong><span>Every fact is known and calculated, but the rulebook itself still needs a human approval before anything releases.</span></button><div class="notice">New run preserves previous runs in this server session. Server restarts clear local runs.</div><div id="corpus-projects"></div></div>`;$('#modal').showModal();loadCorpusProjects();}
/* Real projects from the corpus, with their coverage stated rather than implied.
   A project no playbook can read is listed and disabled — hiding it would make
   the demo look like it covers a drawing set it cannot yet read. */
async function loadCorpusProjects(){
  const host=$('#corpus-projects'); if(!host)return;
  try{
    const projects=(await api('/projects')).filter(p=>!p.seeded);
    if(!projects.length)return;
    host.innerHTML=`<div class="section-heading mt"><h2>Reference projects</h2>${tag('From the client corpus')}</div>`+
      projects.map(p=>{
        const ok=p.readable!==false&&p.playbook;
        return `<button class="scenario-option" ${ok?`onclick="start('clarification',${JSON.stringify(p.project_id).replace(/"/g,'&quot;')})"`:'disabled style="opacity:.55;cursor:not-allowed"'}>
          <strong>${esc(p.project_id)} ${ok?ic('arrowRight'):''}</strong>
          <span>${p.inputs.length} input document${p.inputs.length===1?'':'s'} · ${ok?`read by ${esc(p.playbook)}`:'no playbook reads this element family yet'}${p.has_ground_truth?' · reference bar list available':''}</span>
        </button>`;
      }).join('');
  }catch(e){host.innerHTML=`<p class="explanation mt">Reference projects unavailable: ${esc(e.message)}</p>`;}
}
/* The overview is the first thing a buyer sees. It must answer one question:
   "where is this job right now, and why is the number what it is?" */
function overviewStages(){const d=state.data,items=d.schedule.items||[],conflict=d.elements.some(e=>e.conflicts.length);const released=items.filter(i=>i.release==='released').length;const open=d.questions.length;const done=['done','','',''];
  if(conflict){done[1]='current';}
  else if(open){done[1]='current';}
  else {done[1]='done'; done[2]=items.length?'done':'current';}
  if(items.length&&!open&&!conflict)done[3]=released?'done':'current';
  return done;}
function overview(){const d=state.data,items=d.schedule.items||[],conflict=d.elements.some(e=>e.conflicts.length);const released=items.filter(i=>i.release==='released');const open=d.questions.length;
const status=conflict?'Count conflict':open?'Review required':released.length?'Released':items.length?'Calculation ready':'Input review required';
const headline=conflict?'Two sources disagree. Nothing releases.':open?`${open} facts are missing. Nothing has been guessed.`:released.length?'Every released bar traces back to its source.':'Calculated and waiting on a signature.';
const subline=conflict?'The plan and the schedule give different pile counts. The engine preserved the conflict instead of picking a side, and blocked release for the whole element.':open?'The drawing does not state a cutting-length basis or a spiral run length. Rather than assume a value, the engine stopped and asked — and held the estimate back until an engineer answers.':released.length?`${fmt(d.released_mass_kg,1)} kg of reinforcement released, each line carrying its source, its rule version and the person who approved it.`:'The arithmetic is complete. The rulebook itself still needs an engineer’s sign-off before a single kilogram is released.';
$('#main').innerHTML=head(headline,subline,button(`Open drawing ${ic('arrowUpRight')}`,"go('drawings')",'outline'))+`
<div class="hero"><div class="hero-copy"><div class="eyebrow">RUN STATUS · ${esc(status.toUpperCase())}</div><h2>${released.length?'Released, and defensible.':conflict?'Release blocked at the element.':'Held until the evidence supports it.'}</h2><p>${open?'An estimate built on a guess is a commercial risk. TrustSight surfaces every unstated fact as a specific question, records who answered it and why, and only then lets the number out.':'Every quantity below was produced by deterministic engineering rules from approved facts — not by a model’s best guess.'}</p><div class="hero-actions">${button(`${open?`Answer ${open} question${open===1?'':'s'}`:'Review decisions'} ${ic('arrowRight')}`,"go('review')")}${button('Inspect the drawing',"go('drawings')",'outline')}</div></div>
<div class="hero-image"><div class="hero-stats"><div class="hero-stat"><span>Released mass</span><b>${fmt(d.released_mass_kg,1)} kg</b></div><div class="hero-divider"></div><div class="hero-stat"><span>Held back</span><b>${fmt(d.review_mass_kg,1)} kg</b></div><div class="hero-divider"></div><div class="hero-stat"><span>Open questions</span><b>${open}</b></div><div class="hero-divider"></div><div class="hero-stat"><span>Evidence records</span><b>${d.evidence.records.length}</b></div></div></div></div>
<div class="panel flow-strip">${[['Read the drawing'],['Resolve the gaps'],['Calculate the steel'],['Trace every number']].map(([s],i)=>{const st=overviewStages()[i];return `<div class="flow-stage ${st}"><span class="num">${st==='done'?ic('check',12):'0'+(i+1)}</span>${s}</div>${i<3?'<span class="flow-arrow"></span>':''}`;}).join('')}</div>
<div class="metrics mt">${metric('ELEMENT INSTANCES',fmt(d.elements.reduce((s,e)=>s+e.instances,0)),conflict?'Conflicting source count':d.seeded?'Pile P1 · sample schedule':'Read from source drawing')}${metric('RELEASED MASS',fmt(d.released_mass_kg,1)+' <em>kg</em>',released.length?'Passed every release condition':'Nothing released yet — by design')}${metric('OPEN CLARIFICATIONS',open,conflict?'Plus an element-wide conflict':'Missing facts, never guessed',open?'amber':'')}${metric('EVIDENCE RECORDS',d.evidence.records.length,'Hash chain integrity checked','green')}</div>
<div class="grid-two"><div><div class="section-heading"><h2>Active project</h2>${tag('Session live','green')}</div><div class="panel"><div class="project-row"><div class="project-art">${miniDrawing()}</div><div class="project-info"><b>${d.seeded?'Atlantic Cages · Pile P1':esc(d.run.project_id)}</b><small>${d.seeded?'Sample schematic / S101 + S103':esc(d.document)}</small><div class="project-meta">${tag(d.seeded?'Sample inputs':'Source PDF')}${tag(status,conflict?'red':d.questions.length?'amber':'green')}</div></div>${button(`Open ${ic('arrowRight')}`,"go('drawings')",'outline small')}</div><div class="panel-pad" style="padding-top:0"><div class="progress-line"><i style="width:${conflict?0:released.length/2*100}%"></i></div><div style="display:flex;justify-content:space-between;font-size:10px;color:var(--muted)"><span>${released.length} released BBS lines</span><span>${d.questions.length} questions awaiting review</span></div></div></div>${d.seeded?'':'<div class="notice mt">Real PDF intake uses the pile playbook. Scanned drawings and other element families may remain unresolved. The project rulebook requires approval.</div>'}</div>
<div><div class="section-heading"><h2>Put trust to the test</h2><span class="muted" style="font-size:10px">DEMO SCENARIOS</span></div><div class="panel panel-pad"><div class="scenario"><span class="scenario-icon">?</span><div><b>A detail is missing. What happens?</b><p>Approve a leg dimension and see the bar schedule update.</p><button class="quiet" onclick="go('review')">Explore clarification →</button></div></div><div class="scenario"><span class="scenario-icon" style="background:var(--stop-soft);color:var(--stop)">≠</span><div><b>Two sources disagree.</b><p>Preserve the conflict and prevent an unsupported release.</p><button class="quiet" onclick="start('conflict')">Run conflict scenario →</button></div></div></div></div></div>
<div class="section-space section-heading"><div><h2>Bring your own drawing</h2><p>Native-text pile PDF · up to 25 MB · other drawing families require a new playbook</p></div><label class="button outline" for="upload">${ic('plus')} Open PDF<input id="upload" type="file" accept="application/pdf" hidden onchange="uploadPdf(this)"></label></div>`;}
async function uploadPdf(input){if(!input.files[0])return;toast('Checking PDF…');try{const r=await api('/projects/upload',{method:'POST',headers:{'Content-Type':'application/pdf'},body:input.files[0]});await start('clarification',r.project_id);}catch(e){toast(e.message);input.value='';}}
function miniDrawing(){return '<svg viewBox="0 0 70 75" fill="none" stroke="#597871"><rect x="7" y="7" width="56" height="60"/><path d="M16 20h38M16 25h38M16 30h38M20 36v22h9V36zM37 36v22h9V36zM12 62h46" stroke-width=".7"/></svg>';}
function sampleDrawing(){const conflict=state.data.scenario==='conflict';const resolved=['structured','approval'].includes(state.data.scenario);const circles=Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<circle cx="${478+49*Math.cos(a)}" cy="${230+49*Math.sin(a)}" r="3" fill="#3c5554"/>`;}).join('');return `<svg viewBox="0 0 700 610" role="img" aria-label="Illustrative pile drawing with selectable count, diameter, length and reinforcement callouts. Not for construction."><defs><pattern id="hatch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0v7" stroke="#a3aaa0" stroke-width=".55"/></pattern><marker id="arr" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto-start-reverse"><path d="M6 0L0 3l6 3" fill="none" stroke="#58716b" stroke-width=".7"/></marker></defs><rect x="22" y="22" width="656" height="566" fill="none" stroke="#607367" stroke-width="1"/><g font-family="ui-monospace,monospace" fill="#415b52"><text x="42" y="49" font-size="11" letter-spacing="1">ATLANTIC CAGES / PILE REINFORCEMENT</text><path d="M42 82h616" stroke="#a0aca0"/><text x="43" y="108" font-size="10">PILE SCHEDULE</text><g fill="none" stroke="#7a8a7d" stroke-width=".7"><rect x="43" y="119" width="615" height="55"/><path d="M43 144h615M155 119v55M285 119v55M435 119v55M550 119v55"/></g><g font-size="8"><text x="55" y="135">MARK</text><text x="170" y="135">QUANTITY</text><text x="300" y="135">DIAMETER (mm)</text><text x="450" y="135">LENGTH (mm)</text><text x="565" y="135">LONGITUDINAL</text></g><g font-size="10"><text x="55" y="162">P1</text><text x="170" y="162">6 OFF</text><text x="300" y="162">1000 Ø</text><text x="450" y="162">11,150</text><text x="565" y="162">12–30M</text></g><text x="43" y="205" font-size="9">SECTION A–A</text><g stroke="#5b6f62" fill="none" stroke-width="1"><rect x="120" y="233" width="110" height="257" fill="url(#hatch)"/><rect x="139" y="233" width="72" height="257" fill="#fffef9"/><path d="M145 217v273M205 217v273" stroke-width="2"/>${Array.from({length:17},(_,i)=>`<path d="M137 ${245+i*14}h77" stroke-width=".7"/>`).join('')}<path d="M120 221v-14M230 221v-14M120 209h110" marker-start="url(#arr)" marker-end="url(#arr)"/><path d="M107 233H80M107 490H80M88 233v257" marker-start="url(#arr)" marker-end="url(#arr)"/><path d="M211 275h60l22-17M210 374h49l35-17"/></g><text x="146" y="202" font-size="9">1000 Ø</text><text x="75" y="378" transform="rotate(-90 75 378)" font-size="9">11,150 mm</text><text x="270" y="250" font-size="10">12–30M</text><text x="265" y="347" font-size="10">15M @ 350</text>${resolved?'<text x="250" y="422" font-size="8" fill="#3f8f6f">BAR LEGS: STATED</text><text x="250" y="439" font-size="8" fill="#3f8f6f">SPIRAL RUN: STATED</text>':'<text x="250" y="422" font-size="8" fill="#ab7d3d">BAR LEGS: NOT STATED</text><text x="250" y="439" font-size="8" fill="#ab7d3d">SPIRAL RUN: NOT STATED</text>'}<circle cx="478" cy="260" r="67" fill="url(#hatch)" stroke="#5b6f62"/><circle cx="478" cy="260" r="52" fill="#fffef9" stroke="#5b6f62"/><g transform="translate(0 30)">${circles}</g><path d="M420 349h116" stroke="#58716b" marker-start="url(#arr)" marker-end="url(#arr)"/><text x="448" y="365" font-size="9">1000 Ø</text><text x="418" y="390" font-size="9">PILE CROSS-SECTION</text><text x="420" y="407" font-size="8">12 equally spaced bars</text><text x="43" y="528" font-size="8">${conflict?'CONFLICT NOTE: PLAN SHOWS 8 / SCHEDULE SHOWS 6':'DIMENSIONS IN mm / SCHEMATIC ARRANGEMENT ONLY'}</text><path d="M22 545h656M430 545v43M558 545v43" stroke="#758777"/><text x="42" y="563" font-size="8">TRUSTSIGHT · DEMONSTRATION DRAWING</text><text x="446" y="563" font-size="7">SHEET</text><text x="446" y="579" font-size="10">S101 / S103</text><text x="573" y="563" font-size="7">REVISION</text><text x="573" y="579" font-size="10">DEMO 01</text></g>${[['count',155,144,130,30],['diameter',285,144,150,30],['length',435,144,115,30],['bars',552,144,104,30],['spacing',259,329,95,27]].map(([id,x,y,w,h])=>`<rect tabindex="0" role="button" aria-label="Inspect ${id}" data-fact="${id}" class="hotspot ${state.selected===id?'selected':''}" x="${x}" y="${y}" width="${w}" height="${h}" fill="transparent" stroke="#c8dcd0" stroke-dasharray="4 3"/>`).join('')}</svg>`;}
function factRows(){const e=state.data.elements[0];if(!e)return [];const long=e.reinforcement.find(r=>r.role==='longitudinal'),spiral=e.reinforcement.find(r=>r.role==='spiral');return [ ['count','Pile instances',e.instances,'Schedule quantity','Each pile multiplies the per-element bar count.'],['diameter','Pile diameter',`${fmt(e.geometry?.params?.diameter)} mm`,'Schedule / section','Geometry used for the spatial completeness view.'],['length','Pile length',`${fmt(e.geometry?.params?.length)} mm`,'Pile schedule','Overall pile length is distinct from an approved reinforcement run length.'],['bars','Longitudinal bars',long?`${long.count} × ${long.bar_size}`:'Unresolved','Section callout','An explicit count gives bars per pile. The cutting length still needs leg dimensions.'],['spacing','Spiral spacing',spiral?.spacing_mm?`${spiral.bar_size} @ ${spiral.spacing_mm} mm`:'Unresolved','Reinforcement detail','A spacing alone cannot determine quantity without the reinforced run length.']];}
function relationshipMap(){const d=state.data,e=d.elements[0];if(!e||!d.facts.length)return '';const bySheet={};d.facts.forEach(f=>{const s=f.source?.sheet_no||f.source?.document_id||'—';(bySheet[s]=bySheet[s]||[]).push(f.field);});const sheets=Object.entries(bySheet);if(!sheets.length)return '';return `<div class="panel panel-pad mt"><div class="section-heading"><h2>Cross-sheet relationship map</h2><span class="muted" style="font-size:10px">WHY THESE FACTS BELONG TO ONE ELEMENT</span></div><div class="relationship-map">${sheets.map(([sheet,fields])=>`<div class="rel-sheet"><b>${esc(sheet)}</b><small>${fields.map(f=>esc(f.replaceAll('_',' '))).join(', ')}</small></div><span class="rel-arrow">→</span>`).join('')}<div class="rel-element">${esc(e.mark||'Element')}<small>${e.instances} instance${e.instances===1?'':'s'} · ${esc(e.element_type)}</small></div></div><p class="explanation mt">Every fact above resolves to the same physical element by identity and cross-sheet reference, not by coincidence of file order.</p></div>`;}
function drawings(){const d=state.data;$('#main').innerHTML=head('A drawing. A connected understanding.','Select a detail to inspect its meaning, source and calculation impact.',button(`Review ${d.questions.length} questions ${ic('arrowRight')}`,"go('review')"))+`<div class="drawing-layout"><div class="panel"><div class="panel-title"><span>${d.seeded?'P1 / Reinforcement details':esc(d.document)}</span><div class="tabs"><button class="${state.view==='drawing'?'active':''}" onclick="state.view='drawing';drawings()">Drawing</button><button class="${state.view==='spatial'?'active':''}" onclick="state.view='spatial';drawings()">3D view</button></div></div>${state.view==='drawing'?`<div class="drawing-canvas" id="drawing-canvas">${d.seeded?sampleDrawing():`<img src="/runs/${state.runId}/drawing?page=${state.page}" alt="Source drawing page ${state.page}">`}</div><div class="canvas-foot"><span>${d.seeded?'Select a highlighted schedule cell':'Original PDF rendering · extraction uses native text'}</span><span>${!d.seeded?`<button class="quiet" onclick="changePage(-1)" ${state.page<=1?'disabled':''} aria-label="Previous page">${ic('chevL',13)}</button> ${state.page} / ${state.pages} <button class="quiet" onclick="changePage(1)" ${state.page>=state.pages?'disabled':''} aria-label="Next page">${ic('chevR',13)}</button>`:'S101 / S103 · Sample'}</span></div>`:`<canvas id="scene" class="scene-view" aria-label="Rotatable three-dimensional pile envelope view"></canvas><div class="view-note">Drag to orbit · wheel to zoom · envelope geometry from this run · not a fabrication or BIM model</div>`}</div><div><div class="panel"><div class="panel-title"><span>Resolved drawing facts</span>${tag(d.seeded?'Sample input':'Native text','green')}</div>${factRows().map(([id,label,value,source])=>`<button class="fact ${state.selected===id?'selected':''}" onclick="selectFact('${id}')"><div><label>${label}</label><strong>${esc(value)}</strong><small>${esc(source)}</small></div><span style="color:var(--accent)">${ic('arrowUpRight')}</span></button>`).join('')||'<div class="empty">No supported pile facts found. Review the source PDF.</div>'}</div><div class="panel panel-pad mt" id="fact-detail"></div>${relationshipMap()}<div class="notice mt">${d.scenario==='conflict'?'Count conflict: sample schedule lists 6 piles; plan lists 8. Element-wide release is blocked.':d.questions.length?`${d.questions.length} details still need clarification. Unresolved reinforcement is excluded from calculation.`:'All requested clarifications have answers. Review the schedule and release decisions.'}</div>${d.facts.length?`<details class="panel panel-pad mt"><summary>Source citations (${d.facts.length})</summary>${d.facts.slice(0,12).map(f=>`<p class="explanation"><b>${esc(f.field)}:</b> ${esc(f.value)}<br>${esc(f.source?.sheet_no||f.source?.document_id)} · page ${f.source?.page}</p>`).join('')}</details>`:''}</div></div>`;showFact();document.querySelectorAll('.hotspot').forEach(el=>{el.onclick=()=>selectFact(el.dataset.fact);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectFact(el.dataset.fact);}};});if(state.view==='spatial')drawScene();}
function selectFact(id){state.selected=id;drawings();}
function showFact(){const f=factRows().find(r=>r[0]===state.selected);$('#fact-detail').innerHTML=f?`<div class="eyebrow">WHY THIS MATTERS</div><h3 class="help-title">${f[1]}</h3><p class="explanation">${f[4]}</p><span class="tag">${state.data.seeded?'Sample schematic reference':'See source citations for extracted values'}</span>`:'<p class="explanation">Choose a fact to inspect its engineering meaning.</p>';}
function changePage(delta){state.page=Math.max(1,Math.min(state.pages,state.page+delta));drawings();}
function review(){const d=state.data,conflicts=d.elements.flatMap(e=>e.conflicts),awaitingApproval=d.run.state==='suspended'&&d.run.pending_step===19;$('#main').innerHTML=head('Resolve uncertainty. Keep the evidence.','Every clarification has a value, an owner and a reason.',button(`View schedule ${ic('arrowRight')}`,"go('results')",'outline'))+`<div class="review-layout"><div>${awaitingApproval?approvalGateCard():''}${conflicts.length?`<div class="notice red gap"><b>Element-wide release blocked</b><br>${conflicts.map(esc).join('<br>')}<br>Answering reinforcement questions does not remove this conflict. Start a new clarification scenario to explore a complete release.</div>`:''}${d.questions.length?d.questions.map((q,i)=>questionCard(q,i)).join(''):awaitingApproval?'':`<div class="panel empty"><span style="color:var(--ok)">${ic('check',34)}</span><strong>${conflicts.length?'No missing-field questions':'Clarifications complete'}</strong>${conflicts.length?'The conflicting count still prevents release.':'Approved answers have been applied and the schedule recalculated.'}<p>${button(`Inspect calculated results ${ic('arrowRight')}`,"go('results')")}</p></div>`}${d.schedule.exceptions?.length?`<details class="panel panel-pad mt"><summary style="font-size:12px">Calculation exceptions (${d.schedule.exceptions.length})</summary>${d.schedule.exceptions.map(x=>`<p class="explanation">${esc(x)}</p>`).join('')}</details>`:''}${d.unresolved.length?`<div class="notice mt">${d.unresolved.map(esc).join('<br>')}</div>`:''}</div><div><div class="panel panel-pad"><div class="eyebrow">LIVE RELEASE IMPACT</div><div class="before-after"><div><strong>${fmt(d.released_mass_kg,1)}</strong><small>kg released ${d.seeded?'in sample':''}</small></div><span class="muted">→</span><div><strong>${d.questions.length}</strong><small>questions remaining</small></div></div><p class="explanation mt">An answer triggers a new deterministic calculation. Only supported items progress. The original evidence stays in the history.</p></div><div class="panel panel-pad mt"><div class="section-heading"><h2>Decision history</h2>${tag(d.history.length+' answers','green')}</div>${d.history.length?d.history.map(h=>`<div class="history-record"><b>${esc(h.value.field.replaceAll('_',' '))}</b><p>${esc(JSON.stringify(h.value.value))}</p><p>${esc(h.approver)} · ${new Date(h.timestamp).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</p><p>${esc(h.rationale)}</p></div>`).join(''):'<p class="explanation">No answers yet. Your first decision will appear here with its rationale and timestamp.</p>'}</div></div></div>`;}
function approvalGateCard(){const d=state.data;return `<div class="question-card approval-card"><div style="display:flex;justify-content:space-between">${tag('APPROVAL GATE','red')}${tag('rulebook')}</div><h3>Sign off the rulebook before anything releases</h3><p>${esc(d.rulebook?.version||'This rulebook')} has not been approved by an engineer. Every quantity below is already calculated — the release gate is the only thing withheld, exactly as it would be on a real project with an unsigned assumption sheet.</p><form id="approval-form" onsubmit="submitApproval(event)"><div class="input-grid"><div class="full"><label class="field">Approved by</label><input name="approver" required placeholder="Engineer name or email"></div><div class="full"><label class="field">Approval rationale</label><textarea name="rationale" required placeholder="Basis for signing off this rulebook"></textarea></div></div><div class="form-actions">${d.seeded?`<button type="button" class="quiet" onclick="sampleApproval()">${ic('wand',13)} Fill sample answer</button>`:'<span></span>'}<button class="button" type="submit">Approve rulebook &amp; release ${ic('arrowRight')}</button></div><div class="error" role="alert"></div></form></div>`;}
function sampleApproval(){const f=$('#approval-form');f.elements.approver.value='Lead structural engineer (simulated)';f.elements.rationale.value='Reviewed cover, lap and stock-length rules against the client assumption sheet. Sample walkthrough assumption, not a live-project sign-off.';toast('Sample values filled. Review them before submitting.');}
async function submitApproval(event){event.preventDefault();const f=event.target,btn=f.querySelector('[type=submit]');btn.disabled=true;f.querySelector('.error').textContent='';try{await post(`/runs/${state.runId}/approve`,{token:state.data.run.pending_token,approver:f.elements.approver.value.trim(),answer:{subject:'rulebook_approval',decision:'approved'},rationale:f.elements.rationale.value.trim()});await refresh();review();toast('Rulebook approved. Calculated quantities re-evaluated for release.');}catch(e){f.querySelector('.error').textContent=e.message;btn.disabled=false;}}
function questionCard(q,i){let inputs=q.field==='legs'?`<div><label class="field">Leg A (mm)</label><input name="leg_A" type="number" min="1" step="1" required placeholder="e.g. 510"></div><div><label class="field">Leg B (mm)</label><input name="leg_B" type="number" min="1" step="1" required placeholder="e.g. 11955"></div>${q.role==='spiral'?'<div class="full"><label class="field">Other legs (JSON object)</label><input name="extra_legs" placeholder=\'{"C":2545,"G":300,"O":810}\'></div>':''}`:`<div class="full"><label class="field">${q.field==='run_length_mm'?'Reinforced run length (mm)':esc(q.field.replaceAll('_',' '))}</label><input name="value" ${q.field.endsWith('_mm')?'type="number" min="1" max="100000" step="1"':''} required placeholder="Enter confirmed value"></div>`;return `<div class="question-card"><div style="display:flex;justify-content:space-between">${tag('CLARIFICATION '+String(i+1).padStart(2,'0'),'amber')}${tag(q.role)}</div><h3>${q.field==='legs'?'What is the cutting-length basis?':q.field==='run_length_mm'?'How far does the spiral run?':esc(q.field.replaceAll('_',' '))}</h3><p>${esc(q.question)}</p><form id="question-${i}" onsubmit="submitAnswer(event,${i})"><div class="input-grid">${inputs}<div class="full"><label class="field">Reviewed by</label><input name="approver" required placeholder="Your name or estimator email"></div><div class="full"><label class="field">Decision rationale</label><textarea name="rationale" required placeholder="Document the basis for this answer"></textarea></div></div><div class="form-actions">${state.data.seeded?`<button type="button" class="quiet" onclick="sampleAnswer(${i})">${ic('wand',13)} Fill sample answer</button>`:'<span></span>'}<button class="button" type="submit">Approve &amp; recalculate ${ic('arrowRight')}</button></div><div class="error" role="alert"></div></form></div>`;}
function sampleAnswer(i){const q=state.data.questions[i],f=$('#question-'+i);if(q.field==='legs'){f.elements.leg_A.value=q.role==='longitudinal'?510:140;f.elements.leg_B.value=q.role==='longitudinal'?11955:140;if(f.elements.extra_legs)f.elements.extra_legs.value='{"C":2545,"G":300,"O":810}';}else if(f.elements.value)f.elements.value.value=q.field==='run_length_mm'?12250:q.field==='cover_mm'?75:'';f.elements.approver.value='Demo estimator (simulated)';f.elements.rationale.value=q.field==='legs'?'Sample walkthrough assumption: A 510 mm + B 11,955 mm. Not a live-project instruction.':'Sample walkthrough assumption: reinforced run 12,250 mm at 350 mm spacing, floor-plus-one convention. Not a live-project instruction.';toast('Sample values filled. Review them before submitting.');}
async function submitAnswer(event,i){event.preventDefault();const f=event.target,q=state.data.questions[i],btn=f.querySelector('[type=submit]');btn.disabled=true;f.querySelector('.error').textContent='';try{let value;if(q.field==='legs'){value={A:Number(f.elements.leg_A.value),B:Number(f.elements.leg_B.value)};if(f.elements.extra_legs?.value)value={...value,...JSON.parse(f.elements.extra_legs.value)};}else value=q.field.endsWith('_mm')?Number(f.elements.value.value):f.elements.value.value;const old=state.data.released_mass_kg;await post(`/runs/${state.runId}/clarifications`,{field_name:q.field,value,element_type:'pile',mark:state.data.elements.find(e=>q.element.endsWith(e.mark))?.mark||null,role:q.role,approver:f.elements.approver.value.trim(),rationale:f.elements.rationale.value.trim()});await refresh();review();toast(`Answer recorded. Released mass: ${fmt(old,1)} → ${fmt(state.data.released_mass_kg,1)} kg.`);}catch(e){f.querySelector('.error').textContent=e.message;btn.disabled=false;}}
function results(){const d=state.data,s=d.schedule,items=s.items||[];state.selectedItem=Math.min(state.selectedItem,Math.max(0,items.length-1));$('#main').innerHTML=head('Every bar, accounted for.','Deterministic quantities with a visible basis for every line.',`<a class="button outline" href="/runs/${state.runId}/export/evidence">${ic('download',12)} Evidence JSON</a><a class="button" href="/runs/${state.runId}/export/bbs">${ic('download',12)} Export BBS</a>`)+`<div class="metrics">${metric('CALCULATED BARS',fmt(items.reduce((n,i)=>n+i.quantity,0)),items.length+' schedule lines')}${metric('RELEASED MASS',fmt(d.released_mass_kg,1)+' <em>kg</em>','Passed release conditions','green')}${metric('REVIEW MASS',fmt(d.review_mass_kg,1)+' <em>kg</em>','Calculated but not released')}${metric('OPEN EXCEPTIONS',s.exceptions?.length||0,'Excluded items remain unresolved',s.exceptions?.length?'amber':'')}</div><div class="panel"><div class="panel-title"><span>Bar bending schedule</span>${tag(d.seeded?'Sample · not for construction':'Estimator review required',d.seeded?'':'amber')}</div><div class="table-wrap"><table><thead><tr><th>Bar mark</th><th>Size</th><th>Quantity</th><th>Cut length</th><th>Mass</th><th>Release</th><th></th></tr></thead><tbody>${items.length?items.map((i,n)=>`<tr class="clickable ${n===state.selectedItem?'selected':''}" tabindex="0" onclick="state.selectedItem=${n};results()" onkeydown="if(event.key==='Enter'){state.selectedItem=${n};results()}"><td><b>${esc(i.mark||'—')}</b></td><td>${esc(i.size)}</td><td><span class="traceable" onclick="event.stopPropagation();openTrace(${n})" title="Show how this quantity was derived">${fmt(i.quantity)}</span></td><td><span class="traceable" onclick="event.stopPropagation();openTrace(${n})" title="Show how this length was derived">${fmt(i.cutting_length_mm)} mm</span></td><td><span class="traceable" onclick="event.stopPropagation();openTrace(${n})" title="Show how this mass was derived">${fmt(i.total_mass_kg,1)} kg</span></td><td>${tag(i.release,i.release==='released'?'green':i.release==='block'?'red':'amber')}</td><td><button class="quiet" onclick="event.stopPropagation();openTrace(${n})" style="color:var(--accent-ink);font-weight:600">Trace ${ic('arrowUpRight',12)}</button></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty"><strong>No supported BBS lines yet</strong>Resolve the open questions to calculate the reinforcement.<p>${button(`Review clarifications ${ic('arrowRight')}`,"go('review')",'outline')}</p></div></td></tr>`}</tbody></table></div>${items.length?inspector(items[state.selectedItem]):''}</div>${d.benchmark?benchmark(d.benchmark):''}${s.exceptions?.length?`<div class="notice mt"><b>Unresolved items are excluded from these totals.</b><br>${s.exceptions.map(esc).join('<br>')}</div>`:''}<div class="notice mt">Quantities describe the estimation schedule. Stock splitting, lap design and fabrication approval are outside this demonstration.</div>`;}
function inspector(i){const x=i.explanation;const count=x.count_basis==='explicit count'?`${x.per_instance} bars × ${x.instances} piles`:`(floor(${fmt(x.run_length_mm)} / ${fmt(x.spacing_mm)}) + 1) × ${x.instances}`;return `<div class="inspector"><div class="section-heading"><h2>Inside the number <span class="muted">/ ${esc(i.mark)}</span></h2>${tag('Deterministic calculation','green')}</div><div class="inspector-grid"><div>${shapeSvg(i)}<p class="explanation">Shape ${esc(i.bend_type)} · schematic, not to scale<br>${esc(x.role)} · ${esc(x.rulebook)}<br>${esc(i.release_reason)}</p></div><div><div class="equation"><small>Quantity</small><b>${count} = ${fmt(i.quantity)} bars</b></div><div class="equation"><small>Cutting length · out-to-out leg sum</small><b>${esc(x.length_basis)} = ${fmt(i.cutting_length_mm)} mm</b></div><div class="equation"><small>Mass · quantity × metres × kg/m</small><b>${i.quantity} × ${i.cutting_length_mm/1000} × ${x.unit_mass} = ${fmt(i.total_mass_kg,1)} kg</b></div></div></div><div class="checklist">${Object.entries(i.gates||{}).filter(([k])=>k.startsWith('g')).map(([k,v])=>{const ok=k==='g4_source_quality'?['native_text','vector_path'].includes(v):v;return `<span style="color:${ok?'var(--accent)':'var(--attn)'}">${ok?ic('check',13):'!'} ${esc(k.replace(/^g\d_/,'').replaceAll('_',' '))}</span>`;}).join('')}</div></div>`;}
/* ── Diagrams ───────────────────────────────────────────────────────────────
   These replace the decorative photographs. A photograph of a rebar cage tells
   a buyer nothing they did not already know; these two drawings carry the two
   claims the product is actually sold on. Both are hand-authored inline SVG:
   no library, no image request, and currentColor so they work in both themes. */

/* Claim: the records are chained, so altering one breaks every hash after it. */
function evidenceChainDiagram(){
  const recs=(state.data.evidence.records||[]);
  if(!recs.length)return '';
  const nodes=recs.slice(0,6).map(r=>({
    kind:String(r.claim_type||'').replaceAll('_',' '),
    hash:String(r.record_id||'').slice(0,8)||'genesis',
    prev:String(r.prev_hash||'').slice(0,8),
  }));
  const W=176,GAP=84,PAD=16,H=140;
  const total=PAD*2+nodes.length*W+(nodes.length-1)*GAP;
  const valid=state.data.evidence.chain_valid;
  const stroke=valid?'var(--ok)':'var(--attn)';
  const body=nodes.map((n,i)=>{
    const x=PAD+i*(W+GAP);
    const arrow=i<nodes.length-1?`
      <line x1="${x+W}" y1="76" x2="${x+W+GAP-8}" y2="76" stroke="currentColor" stroke-width="1.2" marker-end="url(#ts-arrow)" opacity=".55"/>
      <text x="${x+W+GAP/2}" y="66" text-anchor="middle" font-size="10" fill="currentColor" opacity=".6" font-family="ui-monospace,monospace">prev_hash</text>`:'';
    return `
      <rect x="${x}" y="40" width="${W}" height="72" rx="8" fill="none" stroke="currentColor" stroke-width="1.2" opacity=".35"/>
      <text x="${x+14}" y="64" font-size="10" fill="currentColor" opacity=".65" letter-spacing="1.2">${esc(n.kind.toUpperCase())}</text>
      <text x="${x+14}" y="88" font-size="13" fill="${stroke}" font-family="ui-monospace,monospace">${esc(n.hash)}</text>
      <text x="${x+14}" y="104" font-size="9" fill="currentColor" opacity=".5" font-family="ui-monospace,monospace">prev ${esc(n.prev)}</text>
      ${arrow}`;
  }).join('');
  return `<figure class="diagram panel panel-pad">
    <div class="section-heading"><h2>How the chain holds</h2>${tag(valid?'Chain verified':'Chain broken',valid?'green':'amber')}</div>
    <div class="diagram-scroll"><svg viewBox="0 0 ${total} ${H}" role="img" preserveAspectRatio="xMinYMin meet"
      aria-label="Each evidence record stores the hash of the record before it, so altering any record breaks every hash that follows.">
      <defs><marker id="ts-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0.5L6 3.5L0 6.5z" fill="currentColor" opacity=".55"/></marker></defs>
      <text x="${PAD}" y="22" font-size="11" fill="currentColor" opacity=".6" letter-spacing="1.4">RUN ${esc(String(state.runId||'').slice(0,8))} · ${recs.length} RECORDS</text>
      ${body}
    </svg></div>
    <figcaption class="explanation mt">Change one approved value, one source citation or one rule version and every hash downstream stops matching — which is what "verified" on this page is actually asserting.</figcaption>
  </figure>`;
}

/* Claim: AI interprets, but nothing reaches the schedule without deterministic
   arithmetic and a human answer. That division is the whole product. */
function pipelineDiagram(){
  const stages=[
    ['INTERPRET','AI reads the drawing','live'],
    ['UNDERSTAND','facts to one element','live'],
    ['CHALLENGE','gaps become questions','live'],
    ['CALCULATE','deterministic rules','live'],
    ['EXPLAIN','evidence per number','live'],
  ];
  const W=150,GAP=32,PAD=110,TOP=48,H=236;
  const calcX=PAD+3*(W+GAP)+W/2;
  const total=PAD*2+stages.length*W+(stages.length-1)*GAP;
  const boxes=stages.map(([t,s],i)=>{
    const x=PAD+i*(W+GAP);
    const endX=i<stages.length-1?x+W+GAP-8:total-106;
    const arrow=`<line x1="${x+W}" y1="${TOP+34}" x2="${endX}" y2="${TOP+34}" stroke="currentColor" stroke-width="1.2" marker-end="url(#ts-arrow2)" opacity=".5"/>`;
    return `
      <rect x="${x}" y="${TOP}" width="${W}" height="68" rx="8" fill="none" stroke="currentColor" stroke-width="1.3" opacity=".4"/>
      <text x="${x+W/2}" y="${TOP+27}" text-anchor="middle" font-size="11" fill="currentColor" letter-spacing="1.1">${t}</text>
      <text x="${x+W/2}" y="${TOP+46}" text-anchor="middle" font-size="10" fill="currentColor" opacity=".6">${s}</text>
      ${arrow}`;
  }).join('');
  const chX=PAD+2*(W+GAP)+W/2;
  return `<figure class="diagram panel panel-pad">
    <div class="section-heading"><h2>Where the AI stops and the engineering starts</h2>${tag('Live in this demo','green')}</div>
    <div class="diagram-scroll"><svg viewBox="0 0 ${total} ${H}" role="img" preserveAspectRatio="xMinYMin meet"
      aria-label="A drawing passes through interpretation, understanding, challenge, deterministic calculation and explanation before becoming a bar schedule. The challenge stage routes unstated facts to an estimator, whose approved answer re-enters the calculation.">
      <defs><marker id="ts-arrow2" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0.5L6 3.5L0 6.5z" fill="currentColor" opacity=".5"/></marker></defs>
      <rect x="8" y="${TOP}" width="88" height="68" rx="8" fill="none" stroke="currentColor" stroke-width="1.3" opacity=".55" stroke-dasharray="4 3"/>
      <text x="52" y="${TOP+33}" text-anchor="middle" font-size="11" fill="currentColor">DRAWING</text>
      <text x="52" y="${TOP+50}" text-anchor="middle" font-size="10" fill="currentColor" opacity=".6">PDF</text>
      <line x1="96" y1="${TOP+34}" x2="${PAD-8}" y2="${TOP+34}" stroke="currentColor" stroke-width="1.2" marker-end="url(#ts-arrow2)" opacity=".5"/>
      ${boxes}
      <rect x="${total-98}" y="${TOP}" width="90" height="68" rx="8" fill="none" stroke="var(--ok)" stroke-width="1.6"/>
      <text x="${total-53}" y="${TOP+31}" text-anchor="middle" font-size="11" fill="var(--ok)">BAR</text>
      <text x="${total-53}" y="${TOP+48}" text-anchor="middle" font-size="11" fill="var(--ok)">SCHEDULE</text>
      <path d="M${chX} ${TOP+68} v34 h-${chX-PAD-40} v28" fill="none" stroke="var(--attn)" stroke-width="1.3" marker-end="url(#ts-arrow2)"/>
      <text x="${chX+10}" y="${TOP+92}" font-size="10" fill="var(--attn)">asks — never assumes</text>
      <rect x="${PAD-40-70}" y="${TOP+130}" width="140" height="56" rx="8" fill="none" stroke="var(--attn)" stroke-width="1.3"/>
      <text x="${PAD-40}" y="${TOP+153}" text-anchor="middle" font-size="11" fill="var(--attn)">ESTIMATOR</text>
      <text x="${PAD-40}" y="${TOP+170}" text-anchor="middle" font-size="10" fill="var(--attn)" opacity=".85">answers, with a reason</text>
      <path d="M${PAD-40+70} ${TOP+158} H${calcX} V${TOP+76}" fill="none" stroke="var(--attn)" stroke-width="1.3" stroke-dasharray="5 3" marker-end="url(#ts-arrow2)"/>
      <text x="${calcX+12}" y="${TOP+152}" font-size="10" fill="var(--attn)">approved fact re-enters the calculation</text>
    </svg></div>
    <figcaption class="explanation mt">The model reads. It never decides. Everything between CALCULATE and BAR SCHEDULE is deterministic arithmetic over facts a person approved — which is why the output is defensible to a client, an auditor or a court.</figcaption>
  </figure>`;
}

/* Evidence drawer. The product's claim is "every number has a story" — so the
   story has to be one click from the number, not one tab away. */
function openTrace(n){const i=(state.data.schedule.items||[])[n];if(!i)return;const x=i.explanation;
const count=x.count_basis==='explicit count'?`${x.per_instance} bars × ${x.instances} piles`:`(floor(${fmt(x.run_length_mm)} / ${fmt(x.spacing_mm)}) + 1) × ${x.instances}`;
/* Surface the records that actually produced this line: anything naming the
   bar mark or its reinforcement role, plus every human approval. */
const needles=[i.mark,x.role,i.size].filter(Boolean).map(v=>String(v).toLowerCase());
const all=state.data.evidence.records||[];
let records=all.filter(r=>{const s=(String(r.subject||'')+' '+JSON.stringify(r.value??'')).toLowerCase();return r.claim_type==='approval'||needles.some(n=>s.includes(n));});
if(!records.length)records=all.slice(-4);
records=records.slice(0,6);
const gates=Object.entries(i.gates||{}).filter(([k])=>k.startsWith('g'));
$('#drawer-root').innerHTML=`<div class="drawer-scrim" onclick="closeDrawer()"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="Derivation of ${esc(i.mark||'this line')}">
<div class="drawer-head"><div><div class="eyebrow">INSIDE THE NUMBER</div><h2>${esc(i.mark||'Schedule line')} · ${fmt(i.total_mass_kg,1)} kg</h2><small>${esc(x.role)} · ${esc(i.size)} · shape ${esc(i.bend_type)}</small></div><button class="quiet" onclick="closeDrawer()" aria-label="Close">${ic('close',16)}</button></div>
<div class="drawer-body">
<div class="equation"><small>1 · Quantity — ${esc(x.count_basis)}</small><b>${count} = ${fmt(i.quantity)} bars</b></div>
<div class="equation"><small>2 · Cutting length — out-to-out leg sum</small><b>${esc(x.length_basis)} = ${fmt(i.cutting_length_mm)} mm</b></div>
<div class="equation"><small>3 · Mass — quantity × metres × kg/m</small><b>${i.quantity} × ${i.cutting_length_mm/1000} × ${x.unit_mass} = ${fmt(i.total_mass_kg,1)} kg</b></div>
<div class="section-heading mt"><h2>Release gates</h2>${tag(i.release,i.release==='released'?'green':i.release==='block'?'red':'amber')}</div>
<div class="checklist">${gates.map(([k,v])=>{const ok=k==='g4_source_quality'?['native_text','vector_path'].includes(v):v;return `<span style="color:${ok?'var(--ok)':'var(--attn)'}">${ok?ic('check',13):'!'} ${esc(k.replace(/^g\d_/,'').replaceAll('_',' '))}</span>`;}).join('')}</div>
<p class="explanation mt">${esc(i.release_reason)}</p>
<div class="section-heading mt"><h2>Governing rulebook</h2>${tag(esc(x.rulebook))}</div>
<p class="explanation">Spacing convention and rounding come from the approved assumption sheet, not from the drawing. Change the rulebook and every dependent number recalculates with a new evidence record.</p>
${records.length?`<div class="section-heading mt"><h2>Evidence chain</h2>${tag(records.length+' records','green')}</div><div class="trace">${records.map(r=>`<details><summary>${tag(r.claim_type.replaceAll('_',' '),r.claim_type==='approval'?'amber':'green')}<span>${esc(String(r.subject).slice(0,60))}</span></summary><pre>${esc(JSON.stringify({value:r.value,source:r.source,produced_by:r.produced_by,approver:r.approver,record_id:r.record_id,prev_hash:r.prev_hash},null,2))}</pre></details>`).join('')}</div>`:''}
</div>
<div class="drawer-foot"><a class="button outline small" href="/runs/${state.runId}/export/evidence">${ic('download',12)} Download the full evidence chain</a></div></aside>`;
document.body.style.overflow='hidden';
$('.drawer .quiet')?.focus();}
function closeDrawer(){$('#drawer-root').innerHTML='';document.body.style.overflow='';}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();});
function shapeSvg(i){return `<svg class="shape-art" viewBox="0 0 360 145" role="img" aria-label="Schematic of bar shape ${esc(i.bend_type)}"><g fill="none" stroke="#367d6d" stroke-width="5" stroke-linecap="round">${i.bend_type==='2'?'<path d="M62 38v65q0 12 13 12h226"/>':'<path d="M115 115c-60-32-24-94 45-94 95 0 103 104 9 104-69 0-87-85-19-91 72-8 94 74 36 83"/>'}</g><g fill="#607a70" font-family="monospace" font-size="10">${i.bend_type==='2'?`<text x="23" y="79">A ${i.legs.A}</text><text x="155" y="100">B ${i.legs.B}</text>`:`<text x="248" y="62">A ${i.legs.A}</text><text x="248" y="82">B ${i.legs.B}</text><text x="248" y="102">C ${i.legs.C}</text><text x="20" y="137">O is a geometry parameter; excluded from leg sum</text>`}</g></svg>`;}
function benchmark(b){return `<div class="section-space"><div class="section-heading"><div><h2>${state.data.seeded?'Sample target comparison':'Reference comparison'}</h2><p style="margin-top:5px">${esc(b.label)}</p></div>${tag(b.rows.filter(r=>r.match).length+' / '+b.rows.length+' lines match','green')}</div><div class="panel table-wrap"><table><thead><tr><th>Mark</th><th>Target quantity</th><th>Calculated quantity</th><th>Target length</th><th>Calculated length</th><th>Outcome</th></tr></thead><tbody>${b.rows.map(r=>`<tr><td>${esc(r.mark)}</td><td>${r.reference_quantity}</td><td>${r.generated_quantity??'—'}</td><td>${fmt(r.reference_length_mm)} mm</td><td>${r.generated_length_mm===null?'—':fmt(r.generated_length_mm)+' mm'}</td><td>${tag(r.match?'Match':r.generated_quantity===null?'Not calculated':'Variance',r.match?'green':'amber')}</td></tr>`).join('')}</tbody></table></div></div>`;}
function baselineResult(d){const mins=state.baselineMinutes;if(!mins)return 'Enter your own manual baseline to see measured time saved. This demo reports machine time only — the automation percentage depends on your estimator’s baseline, never an invented figure.';const machineMin=(d.run.roi.machine_ms||0)/60000;const savedPct=Math.max(0,Math.min(100,Math.round((1-machineMin/mins)*100)));return `Manual baseline: <b>${mins} min</b> · Machine time: <b>${machineMin<0.01?'&lt;0.01':machineMin.toFixed(2)} min</b> · Estimated time saved: <b>${savedPct}%</b><br><small>Illustrative only. Measure a real baseline across many elements, not one sample pile, before quoting an automation percentage.</small>`;}
function baselinePanel(d){return `<div class="panel panel-pad mt"><div class="section-heading"><h2>Measured ROI</h2><span class="muted" style="font-size:10px">AGAINST YOUR BASELINE</span></div><label class="field">Manual baseline for this element (minutes)</label><input id="baseline-input" type="number" min="1" step="1" placeholder="e.g. 45" value="${state.baselineMinutes||''}" oninput="updateBaseline(this.value)"><div id="baseline-result" class="explanation mt">${baselineResult(d)}</div></div>`;}
function updateBaseline(v){state.baselineMinutes=Number(v)||null;try{localStorage.setItem('trustsight-baseline',state.baselineMinutes||'');}catch{}const r=$('#baseline-result');if(r)r.innerHTML=baselineResult(state.data);}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function playWalkthrough(){const btn=$('#walkthrough');if(state.playing){state.playing=false;btn.innerHTML=ic('play')+'<span>Walkthrough</span>';return;}state.playing=true;btn.innerHTML=ic('stop')+'<span>Stop</span>';const seq=['overview','drawings','review','results','evidence'];for(const tab of seq){if(!state.playing)break;go(tab);await sleep(3400);}state.playing=false;btn.innerHTML=ic('play')+'<span>Walkthrough</span>';}
function evidence(){const d=state.data,executed=d.steps.filter(s=>s.status==='executed');$('#main').innerHTML=head('A transparent chain of decisions.','Inspect the source, the rule, the calculation and the human answer.',`<a class="button outline" href="/runs/${state.runId}/export/evidence">${ic('download',12)} Download evidence</a>`)+`${evidenceChainDiagram()}<div class="metrics">${metric('CHAIN INTEGRITY',d.evidence.chain_valid?'Verified':'Invalid',esc(d.evidence.verification),d.evidence.chain_valid?'green':'amber')}${metric('EXECUTED STEPS',executed.length,'Of 23 architecture steps')}${metric('MACHINE TIME',fmt(d.run.roi.machine_ms)+' <em>ms</em>','Measured computation; excludes review')}${metric('KNOWLEDGE REUSE',d.run.roi.reused_knowledge,'Approved facts reused this pass')}</div><div class="grid-two"><div class="panel panel-pad"><div class="section-heading"><h2>Evidence timeline</h2>${tag(d.evidence.records.length+' records')}</div><div class="trace">${d.evidence.records.map(r=>`<details><summary>${tag(r.claim_type.replaceAll('_',' '),r.claim_type==='approval'?'amber':'green')}<span>${esc(r.subject.length>55?r.subject.slice(0,52)+'…':r.subject)}</span></summary><pre>${esc(JSON.stringify({value:r.value,source:r.source,produced_by:r.produced_by,approver:r.approver,rationale:r.rationale,timestamp:r.timestamp,record_id:r.record_id,prev_hash:r.prev_hash},null,2))}</pre></details>`).join('')}</div></div><div><div class="panel panel-pad"><div class="eyebrow">RULEBOOK IN USE</div><h3 class="help-title">${esc(d.rulebook.version)}</h3><p class="explanation">Cover: ${esc(JSON.stringify(d.rulebook.cover_mm))} mm<br>Rounding: ${d.rulebook.rounding_mm} mm<br>Spacing: ${esc(d.rulebook.spacing_convention)}<br>Approved by: ${esc(d.rulebook.approved_by||'Not approved')}</p>${tag(d.seeded?'Sample rulebook':'Project approval pending',d.seeded?'':'amber')}</div><div class="panel panel-pad mt"><div class="section-heading"><h2>Construction controls</h2></div>${d.controls.map(c=>`<div style="border-bottom:1px solid var(--line);padding:11px 0"><div style="display:flex;justify-content:space-between;font-size:11px"><b>${esc(c.control_id)}</b>${tag(c.status,c.status==='pass'?'green':c.status==='not_applicable'?'':'amber')}</div><p class="explanation" style="margin-bottom:0">${esc(c.requirement)}<br>${esc(c.rationale)}</p></div>`).join('')}</div>${baselinePanel(d)}</div></div><div class="section-space"><div class="section-heading"><h2>What actually ran</h2>${tag('Execution transparency','green')}</div><div class="notice gap">This walkthrough uses ${executed.length} implemented deterministic handlers. Model-powered extraction and specialist agents are not invoked in this local run. The remaining architecture stages are explicitly shown as not run.</div><div class="panel">${d.steps.map(s=>`<div class="process-row"><span class="process-no">${s.status==='executed'&&s.ok?ic('check',12):s.no}</span><span>${esc(s.name.replaceAll('_',' '))}</span><span class="mono muted">${esc(s.kind)}</span>${tag(s.ok===false?'Failed':s.status,s.ok===false?'red':s.status==='executed'?'green':'')}</div>`).join('')}</div></div>`;}
function capabilities(){const cards=[['01 / INTERPRET','Read engineering drawings','Native-text pile extraction is connected. Scan-based vision, OCR and broader element interpretation need model integration.','Pile playbook live','green'],['02 / UNDERSTAND','Connect facts to quantities','Link pile counts, bar sizes, dimensions and spacing to the graph and the calculation basis.','Live in this demo','green'],['03 / CHALLENGE','Ask before assuming','Missing leg dimensions and run lengths become specific questions. Conflicting sources block the element.','Live in this demo','green'],['04 / CALCULATE','Make the arithmetic repeatable','The engineering engine computes quantities, leg-based lengths and steel mass from the same approved inputs.','Deterministic engine','green'],['05 / EXPLAIN','Trace every decision','Open a BBS line to inspect its formula, then follow the source, rule version and approval history.','Live in this demo','green'],['06 / VISUALISE','See spatial completeness','Orbit the pile envelopes derived from graph dimensions and placements. Review unresolved geometry.','Live envelope view','green'],['07 / SCALE','Add specialist AI interpretation','Schema-constrained agent modules exist for interpretation workflows. Connect a configured model and validate on held-out drawings.','Integration required','purple'],['08 / COMPARE','Understand drawing revisions','Highlight changed dimensions and their downstream quantity impact across drawing versions.','Proposed next phase','purple'],['09 / OPTIMISE','Plan stock and procurement','Optimise stock cutting, waste and purchasing after lap, stock and fabrication policies are agreed.','Proposed next phase','purple']];$('#main').innerHTML=head('The opportunity goes beyond extraction.','A clear view of what works today and what can come next.',button(`Back to the live demo ${ic('arrowRight')}`,"go('drawings')",'outline'))+`<div class="hero hero-solo"><div class="hero-copy"><div class="eyebrow">FROM SITE TO STRUCTURED DATA</div><h2>Precision measured once.<br>Reused with confidence.</h2><p>Every field survey, every reinforcement detail becomes a governed fact — interpreted by AI, calculated by deterministic engineering rules.</p></div></div>${pipelineDiagram()}<div class="notice green gap"><b>Interpretation + engineering rules + human judgment.</b> This demo proves the governed workflow with sample or native-text pile inputs. It does not call a live language or vision model.</div><div class="cap-grid">${cards.map(([n,title,desc,status,color])=>`<div class="cap-card"><div class="eyebrow">${n}</div><h3>${title}</h3><p>${desc}</p>${tag(status,color)}</div>`).join('')}</div><div class="panel panel-pad section-space"><div class="section-heading"><h2>A practical next pilot</h2>${tag('Measure before scaling')}</div><p class="explanation">Use an unseen drawing set, an estimator-approved rulebook and an independently prepared reference schedule. Measure extraction coverage, quantity variance, review time and unresolved items. Expand to another element family only after that evidence is reviewed.</p></div>`;}
async function drawScene(){const canvas=$('#scene');if(!canvas)return;try{state.scene=await api(`/runs/${state.runId}/scene`);if(!canvas.isConnected)return;const ctx=canvas.getContext('2d'),nodes=state.scene.nodes||[];let yaw=.58,zoom=1,drag=false,lastX=0;let ratio=devicePixelRatio||1;const elements=[];for(const node of nodes){for(const p of node.placements||[])elements.push({node,p});}const maxX=Math.max(1000,...elements.map(e=>e.p.x||0)),length=Math.max(1000,...nodes.map(n=>n.params.length||1000));function paint(){if(!canvas.isConnected)return;const w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*ratio;canvas.height=h*ratio;ctx.scale(ratio,ratio);ctx.fillStyle='#142e37';ctx.fillRect(0,0,w,h);const scale=Math.min(w/(maxX+5000),h/(length+6000))*zoom;const project=(x,y,z)=>{x-=maxX/2;y+=length/2;const rx=x*Math.cos(yaw)+z*Math.sin(yaw),rz=-x*Math.sin(yaw)+z*Math.cos(yaw);return [w/2+rx*scale,h/2-y*scale*.78+rz*scale*.4];};const line=(a,b,color,width=1)=>{ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(...project(...a));ctx.lineTo(...project(...b));ctx.stroke();};for(let x=-5000;x<=maxX+5000;x+=2000)line([x,-length,-5000],[x,-length,5000],'#28454f',.6);for(let z=-5000;z<=5000;z+=2000)line([-5000,-length,z],[maxX+5000,-length,z],'#28454f',.6);elements.forEach(({node,p},idx)=>{const r=(node.params.diameter||0)/2,L=node.params.length||0,color=node.state==='conflicted'?'#e8897f':node.state==='ok'?'#7ccbb1':'#e8c17c',x=p.x||0,z=p.y||0;if(!r||!L)return;for(const y of [0,-L]){for(let i=0;i<48;i++){let a=i*Math.PI/24,b=(i+1)*Math.PI/24;line([x+r*Math.cos(a),y,z+r*Math.sin(a)],[x+r*Math.cos(b),y,z+r*Math.sin(b)],color,1);}}for(let i=0;i<8;i++){const a=i*Math.PI/4;line([x+r*Math.cos(a),0,z+r*Math.sin(a)],[x+r*Math.cos(a),-L,z+r*Math.sin(a)],color+'80',.75);}const pos=project(x,500,z);ctx.font='10px ui-monospace,monospace';ctx.fillStyle='#bed5d8';ctx.textAlign='center';ctx.fillText('P'+(idx+1),...pos);});ctx.textAlign='left';ctx.fillStyle='#d3e8e4';ctx.font='12px sans-serif';ctx.fillText('PILE ENVELOPES / SPATIAL COMPLETENESS',20,28);ctx.font='10px sans-serif';ctx.fillStyle='#8aafb6';ctx.fillText(`${elements.length} placements · ${(length/1000).toFixed(2)} m maximum length · ${state.data.seeded?'sample geometry':'source-derived geometry'}`,20,48);ctx.fillText('Wireframe lines describe concrete envelopes, not individual reinforcing bars.',20,h-18);if(!elements.length){ctx.fillStyle='#d3e8e4';ctx.fillText('No supported placements available for this drawing.',25,h/2);}}canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){yaw+=(e.clientX-lastX)*.008;lastX=e.clientX;paint();}};canvas.onpointerup=()=>drag=false;canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(.5,Math.min(2.5,zoom-e.deltaY*.001));paint();};const ro=new ResizeObserver(()=>paint());ro.observe(canvas);setTimeout(()=>{if(!canvas.isConnected)ro.disconnect();},1000);paint();}catch(e){toast('Spatial view unavailable: '+e.message);}}
$('#reset').onclick=newRun;$('#capabilities-button').onclick=()=>go('capabilities');$('#present').onclick=()=>{document.body.classList.toggle('presentation');$('#present').querySelector('span').textContent=document.body.classList.contains('presentation')?'Exit present':'Present';};$('#walkthrough').onclick=playWalkthrough;$('#print-summary').onclick=()=>{go('results');setTimeout(()=>window.print(),150);};$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
function setTheme(t){document.documentElement.setAttribute('data-theme',t);try{localStorage.setItem('trustsight-theme',t);}catch{}}
$('#theme-toggle').onclick=()=>{const now=document.documentElement.getAttribute('data-theme')==='dark'?'light':'dark';setTheme(now);if(state.view==='spatial'&&state.tab==='drawings')drawings();};
(()=>{try{if(!localStorage.getItem('trustsight-theme'))setTheme(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');}catch{setTheme('light');}})();
try{const savedBaseline=Number(localStorage.getItem('trustsight-baseline'));if(savedBaseline)state.baselineMinutes=savedBaseline;}catch{}
(async()=>{const saved=localStorage.getItem('trustsight-run');if(saved){state.runId=saved;try{await refresh();state.pages=(await api(`/runs/${state.runId}/document`)).pages;go('overview');return;}catch{localStorage.removeItem('trustsight-run');}}await start();})();
